patch:
diff --git a/repro-no-lonely-if.js b/repro-no-lonely-if.js
new file mode 100644
index 0000000..21a3307
--- /dev/null
+++ b/repro-no-lonely-if.js
@@ -0,0 +1,45 @@
+"use strict";
+/* Reproduction: no-lonely-if autofix changes which `if` an outer `else` binds to. */
+const eslintPath = process.env.ESLINT_PATH || "./lib/api";
+const { Linter } = require(eslintPath);
+console.log("ESLint", Linter.version, "from", eslintPath);
+
+const linter = new Linter();
+const config = { rules: { "no-lonely-if": "error" } };
+
+const code = [
+    "if (true)",
+    "\tif (false) {}",
+    "\telse { if (false) {} }",
+    "else throw Error('This `else` should have been unreachable!');",
+    ""
+].join("\n");
+
+const messages = linter.verify(code, config);
+const { output, fixed } = linter.verifyAndFix(code, config);
+
+console.log("--- input ---\n" + code);
+console.log("--- messages ---");
+for (const m of messages) console.log(`${m.line}:${m.column} ${m.ruleId}: ${m.message} (fix: ${m.fix ? JSON.stringify(m.fix) : "none"})`);
+console.log("--- fixed output (fixed=" + fixed + ") ---\n" + output);
+
+function run(src) {
+    try { new Function(src)(); return "ran without throwing"; } catch (e) { return "threw: " + e.message; }
+}
+const before = run(code);
+const after = run(output);
+console.log("--- behavior ---");
+console.log("original:", before);
+console.log("fixed:   ", after);
+
+// Show where the outer `else` binds in the fixed output.
+const espree = require("espree");
+const ast = espree.parse(output, { ecmaVersion: "latest" });
+const outer = ast.body[0];
+console.log("outer `if` has alternate after fix:", Boolean(outer.alternate));
+
+if (before !== after) {
+    console.log("\nBUG REPRODUCED: autofix changed runtime behavior (dangling `else` re-associated with the inner `if`).");
+    process.exit(1);
+}
+console.log("\nNot reproduced.");
